"""Generate a reviewable report and screenshot gallery from recorded results."""
import base64,html,json,pathlib,datetime
from zoneinfo import ZoneInfo
ROOT=pathlib.Path(__file__).resolve().parents[2];OUT=ROOT/'docs/adventures-v1';qa=json.loads((OUT/'qa-results.json').read_text());profile=json.loads((OUT/'profile.json').read_text());inventory=json.loads((ROOT/'public/adventures/inventory.json').read_text());checks=len(qa['checks']);startup=sum(r['bytes']for r in qa['metrics']['startupResources']);date=datetime.datetime.now(ZoneInfo('Australia/Adelaide')).strftime('%d %B %Y, %H:%M %Z')
shots=[('centre','Willowmere village centre','village','The well, market, inn and cottage fronts form a connected village square.'),('street','A residential lane','village','Street-facing cottages, clear paths and small planted gardens.'),('entrance','The Bluebird Inn entrance','village','A detailed premade exterior. The door is decorative; no interior is claimed.'),('bridge','Willowbrook bridge','village','The original arched bridge supplies the visible deck; paving ends at the banks.'),('forest','The woodland edge','wilderness','A separate walking loop, campsite and surrounding pines.'),('woodland','Whispering Wood','wilderness','A distinct woodland world. The camp props and trails stay off the water.'),('meadow','Maker’s Meadow','building','A separate open construction area with its own save.'),('tablet','Tablet player view · 1280 × 800','mobile','Chromium touch emulation. Physical Lenovo performance is unverified.'),('iphone-portrait','Phone player view · 390 × 844','mobile','Joystick, run toggle and a compact header in portrait orientation.'),('iphone-landscape','Phone player view · 844 × 390','mobile','Landscape touch controls remain inside the viewport.'),('places','World selection','interface','Three distinct places and independent saved records.'),('welcome','Opening view','interface','The actual rendered game behind a minimal opening screen.')]
body=''
for stem,title,category,caption in shots:
 path=OUT/'screenshots'/f'{stem}.png';assert path.exists(),path
 body+=f'<figure data-category="{category}"><button class="zoom" aria-label="Enlarge {html.escape(title)}"><img loading="lazy" src="screenshots/{stem}.png" alt="{html.escape(title+": "+caption)}"></button><figcaption><small>{category.upper()}</small><h2>{html.escape(title)}</h2><p>{html.escape(caption)}</p></figcaption></figure>'
gallery='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BlockWorld Adventures · Preview 01 Gallery</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f3e9;color:#294438;font:15px/1.6 system-ui,sans-serif}header,main,footer{max-width:1300px;margin:auto;padding:40px}header{padding-top:65px}.eyebrow,small{font-size:10px;letter-spacing:2px;color:#728268}h1{font:clamp(38px,5vw,66px)/1.1 Georgia,serif;letter-spacing:-2px;margin:20px 0}header p{max-width:760px;color:#697562}.facts{display:flex;gap:12px;flex-wrap:wrap;margin-top:25px}.facts span{border:1px solid #2944382a;border-radius:30px;padding:9px 16px;font-size:12px}nav{display:flex;flex-wrap:wrap;gap:8px}button{font:inherit;color:inherit;cursor:pointer}nav button,dialog button{background:#e6e9dc;border:0;border-radius:20px;padding:10px 18px;font-size:12px}button:focus-visible{outline:3px solid #a48445;outline-offset:4px}nav button[aria-pressed=true]{background:#294438;color:#fff8e7}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin-top:25px}figure{margin:0;overflow:hidden;background:#fffdf4;border:1px solid #29443816;border-radius:17px}.zoom{padding:0;border:0;background:#e6e9dc;width:100%;display:block}figure img{width:100%;height:330px;object-fit:cover;display:block}figure[data-category=mobile] img{object-fit:contain}figcaption{padding:22px}h2{font:26px Georgia,serif;margin:9px 0}figcaption p{font-size:12px;color:#6b7766;margin:0}.note{border-left:3px solid #b79d66;padding:15px 22px;background:#ebe9dc;margin-top:30px;font-size:13px}footer{font-size:12px;color:#74806d}dialog{border:0;padding:15px;border-radius:15px;background:#faf7ed;max-width:95vw;max-height:95vh}dialog::backdrop{background:#15271fe6}dialog img{display:block;max-width:90vw;max-height:82vh;object-fit:contain}dialog button{display:block;margin:10px 0 0 auto}figure[hidden]{display:none}@media(max-width:700px){header,main,footer{padding:25px}.grid{grid-template-columns:1fr}figure img{height:250px}h1{letter-spacing:-1px}.facts{gap:7px}.facts span{font-size:10px;padding:8px 12px}}</style><header><div class="eyebrow">BLOCKWORLD ADVENTURES · DEVELOPMENT PREVIEW 01</div><h1>A village worth<br>getting a little lost in.</h1><p>Actual local browser renders of the premade-asset rebuild. The village, woodland and creative meadow are playable. The original website and Neighborhood 06 are unchanged; this preview has not been deployed.</p><div class="facts"><span>116 deterministic tests passed</span><span>RENDERED_CHECKS rendered & interaction checks</span><span>71 inventoried CC0 assets</span><span>3.27 MB startup resources, uncompressed</span></div><div class="note">Tablet and phone images use Chromium viewport/touch emulation. The managed software renderer measured about 2 fps; physical Lenovo, iPhone and Safari performance remains unverified. Buildings have closed exterior doors and no accessible interiors.</div></header><main><nav aria-label="Filter screenshots"><button aria-pressed="true" data-filter="all">All views</button><button aria-pressed="false" data-filter="village">Village</button><button aria-pressed="false" data-filter="wilderness">Wilderness</button><button aria-pressed="false" data-filter="building">Building area</button><button aria-pressed="false" data-filter="mobile">Mobile</button><button aria-pressed="false" data-filter="interface">Interface</button></nav><div class="grid">FIGURES</div></main><footer>CC0 assets by Kay Lousberg / KayKit and Kenney. Preferred Seahill and Quaternius Nature downloads were blocked; exact sources, licences and substitutions are recorded in the preview package. Dates use Australia/Adelaide.<br>Generated GENERATED_DATE.</footer><dialog><img alt=""><button>Close</button></dialog><script>const d=document.querySelector('dialog');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-filter]').forEach(n=>n.setAttribute('aria-pressed',String(n===b)));document.querySelectorAll('figure').forEach(f=>f.hidden=b.dataset.filter!=='all'&&f.dataset.category!==b.dataset.filter)});document.querySelectorAll('.zoom').forEach(b=>b.onclick=()=>{const i=b.querySelector('img'),target=d.querySelector('img');target.src=i.src;target.alt=i.alt;d.showModal()});d.querySelector('button').onclick=()=>d.close();d.onclick=e=>{if(e.target===d)d.close()};</script></html>'''.replace('FIGURES',body).replace('RENDERED_CHECKS',str(checks)).replace('GENERATED_DATE',date)
(OUT/'gallery.html').write_text(gallery)
report=f'''# BlockWorld Adventures — preview 01

Prepared {date}. Development branch: [codex/blockworld-adventures-asset-rebuild](https://github.com/novice-builder/object-builder/tree/codex/blockworld-adventures-asset-rebuild). **No deployment, publication, main merge or existing website edits were performed.**

The rebuild is playable through `adventures.html`. Willowmere is a designed village with premade cottage/market/inn/windmill architecture, connected paths, planted gardens, a brook crossing and woodland camp. Whispering Wood is a separate rolling pine-forest trail world; Maker’s Meadow is a separate construction area. Each has independent saved records. The original BlockWorld 2.0 entrypoint and useful existing systems remain available unchanged.

## Play and inspect

Unzip `BlockWorld-Adventures-Preview-01.zip`, run `python3 preview.py` (Windows: `py preview.py`), and open `http://localhost:8000/adventures.html`. No npm install or external asset/CDN requests are needed to play the package. ES modules and GLB fetches require HTTP; double-clicking the game HTML directly is not supported. See the included README for same-Wi-Fi tablet/iPhone access. The self-contained output gallery opens directly as an HTML file.

WASD/arrows walk, Shift runs, drag orbits, wheel/pinch zooms, E discovers and B opens Build. Touch uses a left joystick, a second thumb to orbit and a Run toggle. Build supports premade placement, selection, movement, 45-degree rotation, removal, undo and redo. Construction avoids existing footprints, water and public paths; the per-save limit is 200 user objects. Saved objects use reusable asset IDs, paths, scales and transforms from an extensible catalogue.

## Preservation and save integrity

The branch starts at verified Run 4 commit `9f6c14be6b9821c2e6048dc75189338a1b0f9e54`, containing the atomic-menu repair and verified save-ownership correction. No unfinished recovery edits were imported. The existing `Session` and `WorldStore` implementations remain unchanged.

The new scene coordinator reuses `WorldStore` with a separate IndexedDB database, `blockworld-adventures-assets-v1`. It never opens `blockworld2-development` or legacy localStorage. Transitions are serialized; late edits flush before applying a read. Failed saves retain memory and the original record; stale-tab conflicts block overwrites. Native checksummed envelopes retain previous checkpoints. Import validates the adventure extension before creating a new record. A recovered checkpoint does not silently replace the damaged original. Export and Save a new copy remain available, including a selectable text fallback when clipboard or file downloads are unavailable.

The root/Neighborhood 06 preservation check passes. All 25 selected root and historical archive files match the verified baseline byte-for-byte; detailed hashes are in `preservation.json`. Source main remains `1ffd35ed971afa7820734cf10a3287ab546f6306`; website main was observed at `fa78c3ee44f5dbd85f62527fa9c04b37d1fd1382` and was never written by this task. Existing Run 3 and Run 4 branches retain their original remote heads.

## Assets and provenance

{len(inventory)} selected CC0 assets total **{sum(a['sizeBytes']for a in inventory)/1048576:.2f} MiB**. Runtime requests only the selected startup catalogue. Included: KayKit Medieval Hexagon buildings/props, KayKit Adventurers Rogue processed into Explorer, and Kenney Nature Kit GLBs from a CC0 mirror. `adventures/inventory.json` records individual byte counts, hashes, source IDs, triangle counts and mesh-local bounds. `adventures/PROVENANCE.md` records exact source commits, edition evidence and source-adjacent licence copies. The separate Source Assets archive preserves the original selected glTF/bin/png and untrimmed Rogue files; the reproducible packing script is included.

The author pages describe Seahill Towns Complete and Wilds Complete as CC0 name-your-price GLB packs, but the environment blocked their download host. Quaternius Stylized Nature MegaKit’s site was also blocked. Those archives are **not** represented as downloaded or included. Public author repositories and a documented CC0 Kenney mirror supplied the implemented substitutes; no restrictions or paid editions were bypassed. A Quaternius free Medieval Village mirror was downloaded for assessment and remains unused in this runtime.

Explorer retains 13 supplied clips; pruning unused animation buffers reduced it from 3,616,284 to 885,412 bytes. Walking, idle and running use real skeletal clips with crossfades. Controller orientation turns smoothly. The runtime retints named Kenney leaves, bark, grass and tent materials to match the village palette while retaining the original source files.

## Executed checks and actual renders

**116 deterministic tests pass; {checks} distinct browser/render/interaction checks pass.** Strict TypeScript and the local production build pass. Raw unit, save-regression, build and browser evidence is included beside this report. The browser environment is managed Chromium with ANGLE/SwiftShader, not physical hardware or Safari.

The browser checks cover supplied idle/walk/run transitions, acceleration/stopping, blocked building footprints, following-camera shortening before the inn, blocked-spawn recovery, bridge traversal, stream exclusion, trail bank clearance, placement/undo/redo, save/reload, import-as-copy, malformed import rejection, nine world switches, tablet/phone control bounds, partial multitouch release, missing secure-context UUID support and clipboard-free backup text. New deterministic regressions exercise the real IndexedDB store for delayed-read ownership, quota-aborted transitions, recovery copies, stale-tab conflicts and import validation.

The gallery contains actual views of the village centre, street, entrance, bridge, forest, woodland world, meadow, opening screen, world selection and three mobile viewport configurations. Renders were inspected and corrected for tree scale, palette, paving UVs, gaps at path bends, bridge/road intersection, a wet-bank woodland segment, a path-obstructing camp log and header readability. Closed doors are shown honestly; no indoor screenshot is claimed.

## Profile and optimisation

| Measurement | Observed result / limit |
| --- | --- |
| Startup resources | {startup:,} bytes, about {startup/1e6:.2f} MB before server compression; local production origin |
| Model/scene preparation | Approximately {qa['metrics']['desktopReadyMs']/1000:.1f} seconds in one desktop run; {profile['readyMs']/1000:.1f} seconds in a separate profile setup; excludes a real-network or physical-device guarantee |
| Village view | {profile['samples'][-1]['drawCalls']} draw calls and {profile['samples'][-1]['triangles']:,} rendered triangles in the profiled tablet-sized view |
| Texture estimate | Two 1024×1024 asset atlases, about {profile['assets']['estimatedAssetTextureRGBA8Bytes']/1048576:.2f} MiB as RGBA8 plus mipmaps; excludes framebuffer/shadow/procedural texture and driver allocations |
| Repeated switching | Nine switches; generated geometry counts settle within 58–80 and texture counts remain 10 in the measured gentle-quality sequence; bounded in this test, not proof against every possible leak |
| Emulated touch views | 1280×800 tablet; 390×844 portrait phone; 844×390 landscape phone; DPR 1 |
| Software frame samples | About 2 fps in both gentle and balanced samples; this software-rendered environment is slow and does not establish mobile hardware FPS |
| Physical devices / Safari | Unverified |

Optimisations include shared village atlas textures, reusable model geometry/materials, spatially grouped instanced vegetation, automatic frustum culling, removal of unused animation buffer ranges, four concurrent asset loads, bounded object/history limits, explicit scene buffer/material/texture/instance disposal, cached 1024-pixel scenery shadows and a cheap moving character contact shadow. Gentle mode removes shadows and caps DPR at 1; balanced caps DPR at 1.5; high caps DPR at 2. No geometry decimation or unnecessary texture loss was applied. No separate LOD system or texture/mesh codec is claimed.

## Remaining limitations and next priorities

- Physical Lenovo/iPhone and Safari performance is the main validation gap. Test cold loading, sustained walking/orbiting, thermal behaviour, storage/export and 20+ world switches on the actual devices before recommending graphics defaults.
- Prefab buildings are closed exteriors: no opening doors or accessible indoor scenes. The original game retains its existing door/interior systems.
- Collision uses simplified building footprints, tree trunks and an analytic bridge deck. The camera may still intersect foliage canopies; high-speed/edge-case collision and larger user constructions deserve more device testing.
- No dedicated authored turn clip is present; turning combines smooth orientation with supplied locomotion. No jumping interaction, vehicles, NPC life simulation, multiplayer or audio is claimed for the new entrypoint.
- Editing permanent scene pieces is unsupported. Asset catalogue buttons use symbols/text; rendered thumbnails and clearer selection highlighting would improve editing. Quality/run preferences reset on reload.
- Scene loading caches the startup catalogue. The environment has no streaming terrain or LOD system. Further mobile tuning should follow actual hardware measurements.
- Browser saves belong to their origin. Changing address/device requires backup export/import. No service worker or installable app was added, preserving the existing Neighborhood 06 setup.

## Resume

Fetch the development branch, read `docs/ASSET-REBUILD-CONTINUE.md`, check the remote tip and keep existing branches/releases untouched. Run `npm ci --cache /workspace/work/npm-cache`, then `npm run dev:adventures`. Use `npm run build:adventures`, `npm run test:adventures` and the QA scripts under `tools/adventures/`; do not run publishing/release helpers for the original app. Work on the next unfinished priority, checkpoint tests/renders in Git commits, push and verify the remote SHA. New packages must get new version names; never overwrite preview 01 or older releases. Do not deploy without explicit user approval. No banked usage reset was redeemed.
'''
(OUT/'REPORT.md').write_text(report)
print('Gallery/report generated with',checks,'checks and',len(shots),'screenshots')
